#!/usr/bin/env python3
"""protein/predict_structure_monomer — auto-generated run.py (archetype=structure_predict).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "structure_predict"
BRAIN = "protein"
SKILL = "predict_structure_monomer"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'skill_id': 'predict_structure_monomer', 'sequence': '', 'model_path': '', 'plddt_mean': 0.0, 'ptm': 0.0, 'n_residues': 0, 'runtime_sec': 0.0, 'diagnostics': {'brain': 'protein', 'archetype': 'structure_predict'}})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """单体结构预测(默认 esmfold;可切 boltz)。"""
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401
    seq = payload.get("sequence") or payload.get("seq")
    backend = payload.get("backend", "esmfold")  # esmfold | boltz
    out_dir = payload.get("out_dir") or _tempfile.mkdtemp(prefix="monomer_")
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "backend": backend, "out_dir": out_dir}
    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL, "sequence": seq or "", "model_path": "",
                "plddt_mean": 0.0, "ptm": 0.0, "n_residues": 0, "runtime_sec": 0.0,
                "diagnostics": {**diagnostics, "dry": True}}
    if not seq:
        return {"ok": False, "error": "需要 sequence", "diagnostics": diagnostics}
    if backend == "boltz":
        # 写一个 fasta
        fa = _os.path.join(out_dir, "input.fasta")
        _os.makedirs(out_dir, exist_ok=True)
        with open(fa, "w") as fh: fh.write(f">monomer\n{seq}\n")
        cmd = ["boltz", "predict", fa, "--out_dir", out_dir, "--output_format", "pdb",
               "--use_msa_server"]
        t0 = _time.time()
        r = run_tool(cmd, timeout=int(payload.get("timeout_s", 3600)))
    else:
        script = (
            "import json, os, sys, torch\n"
            "import esm\n"
            f"seq = {seq!r}; out_dir = {out_dir!r}\n"
            "os.makedirs(out_dir, exist_ok=True)\n"
            "model = esm.pretrained.esmfold_v1().eval()\n"
            "if torch.cuda.is_available(): model = model.cuda()\n"
            "with torch.no_grad(): out = model.infer_pdb(seq)\n"
            "p = os.path.join(out_dir, 'pred.pdb')\n"
            "with open(p, 'w') as fh: fh.write(out)\n"
            "bfacs = [float(l[60:66]) for l in out.splitlines() if l.startswith('ATOM') and len(l) >= 66]\n"
            "plddt = sum(bfacs)/len(bfacs) if bfacs else 0.0\n"
            "json.dump({'model_path': p, 'plddt_mean': plddt, 'n_residues': len(seq)}, sys.stdout)\n"
        )
        t0 = _time.time()
        r = run_tool(["python3", "-c", script], timeout=int(payload.get("timeout_s", 1200)))
    diagnostics["subprocess"] = {"wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", "monomer predict 失败"),
                "stderr": r.get("stderr", "")[-400:], "diagnostics": diagnostics}
    if backend == "boltz":
        import glob as _glob
        pdbs = sorted(_glob.glob(_os.path.join(out_dir, "**", "*.pdb"), recursive=True))
        return {"ok": True, "skill_id": SKILL, "sequence": seq,
                "model_path": pdbs[0] if pdbs else "",
                "plddt_mean": 0.0, "ptm": 0.0, "n_residues": len(seq),
                "runtime_sec": round(_time.time() - t0, 2), "diagnostics": diagnostics}
    try:
        parsed = json.loads(r["stdout"])
    except json.JSONDecodeError as e:
        return {"ok": False, "error": f"stdout 解析失败: {e}", "diagnostics": diagnostics}
    return {"ok": True, "skill_id": SKILL, "sequence": seq,
            "model_path": parsed.get("model_path", ""),
            "plddt_mean": parsed.get("plddt_mean", 0.0),
            "ptm": 0.0, "n_residues": parsed.get("n_residues", 0),
            "runtime_sec": round(_time.time() - t0, 2), "diagnostics": diagnostics}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
